9|use Illuminate\Http\JsonResponse;
10|use Illuminate\Http\Resources\Json\AnonymousResourceCollection;
11|
12|class TodoController extends Controller
13|{
14|    public function index(UnitScopedRequest $request): AnonymousResourceCollection
15|    {
16|        $accessibleIds = $request->accessibleIds();
17|
18|        $query = Todo::whereIn('unit_id', $accessibleIds)->with('unit:id,name');
19|
20|        if ($request->filled('date')) {
21|            $query->whereDate('start_at', $request->date);
22|        }
23|
24|        if ($request->filled('month') && $request->filled('year')) {
25|            $query->whereMonth('start_at', $request->month)
26|                ->whereYear('start_at', $request->year);
27|        }
28|
29|        if ($request->filled('is_completed')) {
30|            $query->where('is_completed', $request->boolean('is_completed'));
31|        }
32|
33|        $perPage = min((int) $request->input('per_page', 15), 100);
34|        $todos = $query->latest()->paginate($perPage);
35|
36|        return TodoResource::collection($todos);
37|    }
38|
39|    public function store(UnitScopedRequest $request): JsonResponse
40|    {
41|        $validated = $request->validate([
42|            'title' => 'required|string|min:3',
43|            'start_at' => 'required|date',
44|            'end_at' => 'nullable|date|after_or_equal:start_at',
45|            'is_completed' => 'boolean',
46|            'unit_id' => 'nullable|exists:units,id',
47|        ]);
48|
49|        $user = $request->user();
50|
51|        // Explicit unit_id wins; fall back to the user's primary unit (pivot is_primary),
52|        // then to the person's unit — never silently null (#431)
53|        $unitId = $validated['unit_id'] ?? $user->primaryUnit()?->id ?? $user->person?->u_id;
54|
55|        if (! $unitId || ! in_array($unitId, $request->accessibleIds())) {
56|            return response()->json(['message' => 'Unauthorized to create todo in this unit.'], 403);
57|        }
58|
59|        $todo = Todo::create([
60|            'title' => $validated['title'],
61|            'start_at' => $validated['start_at'],
62|            'end_at' => $validated['end_at'] ?? null,
63|            'is_completed' => $validated['is_completed'] ?? false,
64|            'unit_id' => $unitId,
65|            'user_id' => $user->id,
66|        ]);
67|
68|        return response()->json([
69|            'success' => true,
70|            'data' => new TodoResource($todo->load('unit')),
71|        ], 201);
72|    }
73|
74|    public function show(UnitScopedRequest $request, Todo $todo): JsonResponse
75|    {
76|        if (! $this->isTodoAccessible($request, $todo)) {
77|            return response()->json(['message' => 'Unauthorized.'], 403);
78|        }
79|
80|        return response()->json([
81|            'success' => true,
82|            'data' => new TodoResource($todo->load('unit')),
83|        ]);
84|    }
85|
86|    public function update(UnitScopedRequest $request, Todo $todo): JsonResponse
87|    {
88|        if (! $this->isTodoAccessible($request, $todo)) {
89|            return response()->json(['message' => 'Unauthorized to update this todo.'], 403);
90|        }
91|
92|        $validated = $request->validate([
93|            'title' => 'sometimes|required|string|min:3',
94|            'start_at' => 'sometimes|required|date',
95|            'end_at' => 'nullable|date|after_or_equal:start_at',
96|            'is_completed' => 'boolean',
97|        ]);
98|
99|        $todo->update($validated);
100|
101|        return response()->json([
102|            'success' => true,
103|            'data' => new TodoResource($todo->load('unit')),
104|        ]);
105|    }
106|
107|    public function destroy(UnitScopedRequest $request, Todo $todo): JsonResponse
108|    {
109|        if (! $this->isTodoAccessible($request, $todo)) {
110|            return response()->json(['message' => 'Unauthorized to delete this todo.'], 403);
111|        }
112|
113|        $todo->delete();
114|
115|        return response()->json([
116|            'success' => true,
117|            'message' => 'Todo deleted successfully',
118|        ]);
119|    }
120|
121|    public function toggleComplete(UnitScopedRequest $request, Todo $todo): JsonResponse
122|    {
123|        if (! $this->isTodoAccessible($request, $todo)) {
124|            return response()->json(['message' => 'Unauthorized to modify this todo.'], 403);
125|        }
126|
127|        $todo->update(['is_completed' => ! $todo->is_completed]);
128|
129|        return response()->json([
130|            'success' => true,
131|            'data' => new TodoResource($todo->load('unit')),
132|        ]);
133|    }
134|
135|    /**
136|     * Null-unit contract (#838): a null-unit todo belongs to its creator —
137|     * the same rule the Livewire component enforces, so UI and API agree
138|     * row-for-row.
139|     */
140|    private function isTodoAccessible(UnitScopedRequest $request, Todo $todo): bool
141|    {
142|        if ($todo->unit_id === null) {
143|            return $todo->user_id === $request->user()->id;
144|        }
145|
146|        return in_array($todo->unit_id, $request->accessibleIds());
147|    }
