240|    public function stats(UnitScopedRequest $request): JsonResponse
241|    {
242|        $accessibleIds = $request->accessibleIds();
243|
244|        // Issue #217: cache stats to avoid 3 heavy queries per request.
245|        // Key is scoped by (version, accessible units): the version counter is
246|        // bumped on every hardware write (Hardware::flushStatsCache()), which
247|        // invalidates all previously cached scopes without flushing the whole
248|        // cache. Stale entries expire naturally via the 10-minute TTL.
249|        $version = Cache::get('hardware_stats_version', 0);
250|        $cacheKey = "hardware_stats:v{$version}:".md5(json_encode($accessibleIds));
251|
252|        $data = Cache::remember($cacheKey, now()->addMinutes(10), function () use ($accessibleIds) {
253|            $baseQuery = Hardware::join('persons', 'hardwares.n_code', '=', 'persons.n_code')
254|                ->whereIn('persons.u_id', $accessibleIds)
255|                ->select('hardwares.*');
256|
257|            return [
258|                'total' => $baseQuery->count(),
259|                'by_type' => (clone $baseQuery)->select('type', DB::raw('count(*) as count'))
260|                    ->groupBy('type')
261|                    ->pluck('count', 'type')
262|                    ->toArray(),
263|                'shutdown' => (clone $baseQuery)->where('shutdown', true)->count(),
264|            ];
265|        });
266|
267|        return response()->json([
268|            'success' => true,
269|            'data' => $data,
270|        ]);
271|    }
