45|    /**
46|     * Bbox filter for queries with prefixed/aliased columns (JOINs) — Issue #404.
47|     */
48|    protected function applyBboxAliased($query, UnitScopedRequest $request)
49|    {
50|        if (! $request->filled('bbox')) {
51|            return $query;
52|        }
53|
54|        $bbox = explode(',', $request->bbox);
55|        if (count($bbox) !== 4) {
56|            return $query;
57|        }
58|
59|        [$minLon, $minLat, $maxLon, $maxLat] = array_map('floatval', $bbox);
60|
61|        $query->whereBetween('units.lat', [$minLat, $maxLat])
62|            ->whereBetween('units.lng', [$minLon, $maxLon]);
63|
64|        return $query;
