92|    /**
93|     * Build a cache key for GIS endpoints via the unified service.
94|     * Uses the shared 'gis' namespace (incremented on hardware/person changes)
95|     * and includes the endpoint in extra data for per-endpoint separation.
96|     * Sorts accessibleIds to ensure consistent cache keys regardless of DB result order.
97|     */
98|    protected function gisCacheKey(string $endpoint, array $accessibleIds, string $bbox, array $extra = []): string
99|    {
100|        $idStrings = array_map('strval', $accessibleIds);
101|        sort($idStrings, SORT_STRING);
102|        $scopeHash = md5(implode(',', $idStrings));
103|        $extra = array_merge(['endpoint' => $endpoint], $extra);
104|        $extraHash = md5(serialize($extra));
