344|            // Hardware count (in bbox via person.unit) — direct JOIN instead of whereHas (#402)
345|            $hardwareCount = Hardware::join('persons', 'hardwares.n_code', '=', 'persons.n_code')
346|                ->join('units', 'persons.u_id', '=', 'units.id')
347|                ->whereIn('persons.u_id', $accessibleIds)
348|                ->whereNotNull('units.lat')->whereNotNull('units.lng')
349|                ->when($bboxConditions, fn ($q) => $q->where($bboxConditions))
350|                ->count();
351|
352|            // Open tickets count (in bbox via unit) — direct JOIN instead of whereHas (#402)
353|            $ticketsCount = Ticket::join('units', 'tickets.unit_id', '=', 'units.id')
354|                ->whereIn('tickets.unit_id', $accessibleIds)
355|                ->where('tickets.status', '!=', 'completed')
356|                ->whereNotNull('units.lat')->whereNotNull('units.lng')
357|                ->when($bboxConditions, fn ($q) => $q->where($bboxConditions))
358|                ->count();
359|
360|            return [
361|                'units' => $unitsCount,
362|                'hardware' => $hardwareCount,
363|                'open_tickets' => $ticketsCount,
364|            ];
365|        });
366|
367|        return response()->json($data);
368|    }
