370|    /**
371|     * Get clustered units for low zoom levels.
372|     * Query params: zoom, bbox
373|     */
374|    public function clusters(UnitScopedRequest $request): JsonResponse
375|    {
376|        $accessibleIds = $request->accessibleIds();
377|        $bbox = $this->normalizedBbox($request);
378|        $zoom = (int) $request->get('zoom', 10);
379|        $cacheKey = $this->gisCacheKey('clusters', $accessibleIds, $bbox, ['zoom' => $zoom]);
380|
381|        $features = Cache::remember($cacheKey, now()->addMinutes(60), function () use ($accessibleIds, $request, $zoom) {
382|            // Grid size in degrees, adjusted by zoom
383|            $gridSize = max(0.005, 0.5 / pow(2, $zoom - 2));
384|
385|            // Build query with raw SQL for grouping (#400)
386|            // Portable grid bucketing: snap to the nearest grid line via ROUND(l/g)*g —
387|            // equivalent to PostGIS ST_SnapToGrid but works on sqlite/MySQL/PG.
388|            $selectRaw = sprintf(
389|                'COUNT(*) as count,
390|                ROUND(lng / %f) * %f as lng_key,
391|                ROUND(lat / %f) * %f as lat_key,
392|                AVG(lat) as lat,
393|                AVG(lng) as lng',
394|                $gridSize, $gridSize, $gridSize, $gridSize
395|            );
396|
397|            $query = Unit::whereIn('id', $accessibleIds)
398|                ->whereNotNull('lat')->whereNotNull('lng')
399|                ->selectRaw($selectRaw);
400|
401|            $this->applyBbox($query, $request);
402|
403|            $clusters = $query
404|                ->groupBy('lat_key', 'lng_key')
405|                ->get();
406|
407|            return $clusters->map(function ($cluster) {
408|                return [
409|                    'type' => 'Feature',
410|                    'geometry' => [
411|                        'type' => 'Point',
412|                        'coordinates' => [(float) $cluster->lng, (float) $cluster->lat],
413|                    ],
414|                    'properties' => [
415|                        'count' => (int) $cluster->count,
416|                    ],
417|                ];
418|            })->values()->all();
419|        });
420|
421|        return response()->json([
422|            'type' => 'FeatureCollection',
423|            'features' => $features,
424|        ]);
425|    }
