51|                                 FROM persons p LEFT JOIN estekhdams e ON p.e_id = e.id
52|                                 WHERE p.e_id IS NOT NULL AND p.u_id = ANY(?) GROUP BY p.e_id, e.name) x) AS by_estekhdam,
53|                        (SELECT coalesce(jsonb_object_agg(coalesce(x.name, x.r_id::text), x.c), '{}')
54|                           FROM (SELECT p.r_id, r.name, count(*) AS c
55|                                 FROM persons p LEFT JOIN radifs r ON p.r_id = r.id
56|                                 WHERE p.r_id IS NOT NULL AND p.u_id = ANY(?) GROUP BY p.r_id, r.name) x) AS by_radif",
57|                    [$idArray, $idArray, $idArray, $idArray, $idArray, $idArray]
58|                );
