104|    public function personnel(UnitScopedRequest $request): JsonResponse
105|    {
106|        $accessibleIds = $request->accessibleIds();
107|
108|        $query = Person::leftJoin('units', 'persons.u_id', '=', 'units.id')
109|            ->leftJoin('semats', 'persons.s_id', '=', 'semats.id')
110|            ->leftJoin('tahsils', 'persons.t_id', '=', 'tahsils.id')
111|            ->leftJoin('estekhdams', 'persons.e_id', '=', 'estekhdams.id')
112|            ->leftJoin('radifs', 'persons.r_id', '=', 'radifs.id')
113|            ->whereIn('persons.u_id', $accessibleIds)
114|            ->select(
115|                'persons.*',
116|                'units.name as unit_name',
117|                'semats.name as semat_name',
118|                'tahsils.name as tahsil_name',
119|                'estekhdams.name as estekhdam_name',
120|                'radifs.name as radif_name',
121|            );
122|
123|        $p = 'persons.';
124|        if ($request->filled('search')) {
125|            $s = self::normalizeForQuery($request->search);
126|            $query->where(function ($q) use ($s, $p) {
127|                $q->where($p.'n_code', 'LIKE', "%{$s}%")
128|                    ->orWhere($p.'f_name', 'LIKE', "%{$s}%")
129|                    ->orWhere($p.'l_name', 'LIKE', "%{$s}%")
130|                    ->orWhereRaw("CONCAT({$p}f_name, ' ', {$p}l_name) LIKE ?", ["%{$s}%"]);
131|            });
132|        }
133|        foreach (['unit_id' => 'u_id', 'semat_id' => 's_id', 'tahsil_id' => 't_id', 'estekhdam_id' => 'e_id', 'radif_id' => 'r_id', 'status' => 'status'] as $param => $col) {
134|            if ($request->filled($param)) {
135|                $query->where($p.$col, $request->{$param});
136|            }
137|        }
138|
139|        $perPage = min((int) $request->get('per_page', 20), 100);
140|        $persons = $query->paginate($perPage);
141|
142|        // Rebuild the nested relation shape the clients expect
143|        $items = $persons->getCollection()->map(function ($person) {
144|            $data = $person->toArray();
145|            $names = [
146|                'unit' => ['id' => $data['u_id'], 'name' => $data['unit_name']],
147|                'semat' => ['id' => $data['s_id'], 'name' => $data['semat_name']],
148|                'tahsil' => ['id' => $data['t_id'], 'name' => $data['tahsil_name']],
149|                'estekhdam' => ['id' => $data['e_id'], 'name' => $data['estekhdam_name']],
150|                'radif' => ['id' => $data['r_id'], 'name' => $data['radif_name']],
151|            ];
152|            foreach ([
153|                'unit_name', 'semat_name', 'tahsil_name', 'estekhdam_name', 'radif_name',
154|            ] as $alias) {
155|                unset($data[$alias]);
156|            }
157|
158|            return array_merge($data, $names);
159|        });
160|
161|        return response()->json([
162|            'data' => $items->values(),
163|            'meta' => [
164|                'current_page' => $persons->currentPage(),
165|                'last_page' => $persons->lastPage(),
166|                'per_page' => $persons->perPage(),
167|                'total' => $persons->total(),
168|            ],
169|        ]);
