17|    /**
18|     * GET /api/hr/org-chart — full org tree with personnel counts per unit.
19|     */
20|    public function orgChart(UnitScopedRequest $request): JsonResponse
21|    {
22|        $accessibleIds = $request->accessibleIds();
23|
24|        $data = Cache::remember(
25|            $this->hrStatsCacheKey($accessibleIds, 'orgchart'),
26|            now()->addMinutes(10),
27|            function () use ($accessibleIds) {
28|                $units = Unit::whereIn('id', $accessibleIds)
29|                    ->withCount(['person as personnel_count'])
30|                    ->get();
31|
32|                // Build nested tree from flat list (parent_id references).
33|                // The else-branch below is the same predicate UnitTreeService::roots()
34|                // applies (parent is null, or the parent is out of scope) — see
35|                // issue #704. It stays inline here deliberately: the loop already
36|                // holds every accessible unit in $byId, so calling roots() would
37|                // re-query the same rows to learn something this loop can read off
38|                // directly. The Livewire `unit.tree` component, which does NOT
39|                // already have the flat list in hand, uses the service.
40|                $byId = $units->keyBy('id');
41|                $tree = [];
42|                foreach ($units as $unit) {
43|                    if ($unit->parent_id && $byId->has($unit->parent_id)) {
44|                        $byId[$unit->parent_id]->children ??= [];
45|                        $byId[$unit->parent_id]->children[] = $unit;
46|                    } else {
47|                        $tree[] = $unit;
48|                    }
49|                }
50|
51|                $format = function ($unit) use (&$format) {
52|                    return [
53|                        'id' => $unit->id,
54|                        'name' => $unit->name,
55|                        'parent_id' => $unit->parent_id,
56|                        'personnel_count' => $unit->personnel_count,
57|                        'children' => isset($unit->children)
58|                            ? collect($unit->children)->map($format)->values()
59|                            : [],
60|                    ];
61|                };
62|
63|                return collect($tree)->map($format)->values();
64|            }
65|        );
66|
67|        return response()->json(['data' => $data]);
68|    }
69|
70|    /**
71|     * GET /api/hr/org-chart/expandable — expandable org chart with initial_limit.
72|     * Returns first N root units; children loaded on-demand via loadSubtree.
73|     */
74|    public function orgChartExpandable(UnitScopedRequest $request): JsonResponse
75|    {
76|        $accessibleIds = $request->accessibleIds();
77|        $initialLimit = min((int) $request->get('initial_limit', 20), 100);
78|
79|        $scopeHash = md5(implode(',', $accessibleIds));
80|        $version = Cache::get('hr_stats_version', 0);
81|        $cacheKey = "hr:expandable:v{$version}:{$scopeHash}:{$initialLimit}";
82|
83|        $units = Cache::remember($cacheKey, now()->addMinutes(10), function () use ($accessibleIds, $initialLimit) {
84|            return Unit::whereIn('id', $accessibleIds)
85|                ->withCount(['person as personnel_count', 'children as has_children'])
86|                ->with('unitType:id,name')
87|                ->orderBy('name')
88|                ->limit($initialLimit)
89|                ->get()
90|                ->map(fn (Unit $u) => [
91|                    'id' => $u->id,
92|                    'name' => $u->name,
93|                    'parent_id' => $u->parent_id,
94|                    'unit_type' => $u->unitType?->name,
95|                    'personnel_count' => $u->personnel_count,
96|                    'has_children' => $u->has_children > 0,
97|                    'level' => 1,
98|                ]);
99|        });
100|
101|        return response()->json([
102|            'data' => $units->values(),
103|            'meta' => ['initial_limit' => $initialLimit],
104|        ]);
105|    }
106|
107|    /**
108|     * GET /api/hr/org-chart/subtree/{unitId} — load entire subtree for a unit.
109|     */
110|    public function loadSubtree(UnitScopedRequest $request, int $unitId): JsonResponse
111|    {
112|        $accessibleIds = $request->accessibleIds();
113|
114|        if (! in_array($unitId, $accessibleIds)) {
115|            return response()->json(['message' => 'Unit not accessible.'], 403);
116|        }
117|
118|        $scopeHash = md5(implode(',', $accessibleIds));
119|        $result = app(CacheInvalidationServiceInterface::class)
120|            ->remember('unit_hierarchy', $scopeHash, function () use ($accessibleIds, $unitId) {
121|                $units = Unit::whereIn('id', $accessibleIds)
122|                    ->subtree($unitId)
123|                    ->withCount('person as personnel_count')
124|                    ->with('unitType:id,name')
125|                    ->get();
126|
127|                $byId = $units->keyBy('id');
128|                $root = $byId->get($unitId);
129|
130|                if (! $root) {
131|                    return [];
132|                }
133|
134|                $children = $units->filter(fn (Unit $u) => $u->parent_id == $unitId);
135|
136|                $format = function (Unit $unit) use (&$format, $byId) {
137|                    $childUnits = $byId->filter(fn (Unit $u) => $u->parent_id == $unit->id);
138|
139|                    return [
140|                        'id' => $unit->id,
141|                        'name' => $unit->name,
142|                        'parent_id' => $unit->parent_id,
143|                        'unit_type' => $unit->unitType?->name,
144|                        'personnel_count' => $unit->personnel_count,
145|                        'has_children' => $childUnits->isNotEmpty(),
146|                        'children' => $childUnits->map(fn (Unit $c) => $format($c))->values(),
147|                    ];
148|                };
149|
150|                return collect($children)->map(fn (Unit $c) => $format($c))->values();
151|            }, 10, ['subtree' => $unitId]);
152|
153|        return response()->json(['data' => $result]);
154|    }
