2|
3|namespace App\Http\Controllers\Api;
4|
5|use App\Http\Controllers\Controller;
6|use App\Http\Requests\UnitScopedRequest;
7|use App\Traits\PersianNormalizer;
8|use Illuminate\Http\JsonResponse;
9|use Illuminate\Support\Facades\Cache;
10|use Illuminate\Support\Facades\DB;
11|
12|/**
13| * HR time-series analytics — extracted from HrController.
14| */
15|class HrAnalyticsController extends Controller
16|{
17|    use PersianNormalizer;
18|
19|    /**
20|     * GET /api/hr/analytics/headcount-trend — monthly headcount for last N months.
21|     */
22|    public function headcountTrend(UnitScopedRequest $request): JsonResponse
23|    {
24|        $accessibleIds = $request->accessibleIds();
25|        $months = min((int) $request->get('months', 12), 24);
26|
27|        $data = Cache::remember(
28|            $this->hrAnalyticsCacheKey('headcount_trend', $accessibleIds, $months),
29|            now()->addMinutes(5),
30|            function () use ($accessibleIds, $months) {
31|                $since = now()->subMonths($months)->startOfMonth();
32|
33|                $idArray = '{'.implode(',', array_map('intval', $accessibleIds)).'}';
34|                $results = DB::select(
35|                    "SELECT to_char(date_trunc('month', created_at), 'YYYY-MM') AS month,
36|                            COUNT(*) AS count
37|                     FROM persons
38|                     WHERE u_id = ANY(?)
39|                       AND created_at >= ?
40|                     GROUP BY date_trunc('month', created_at)
41|                     ORDER BY date_trunc('month', created_at) ASC",
42|                    [$idArray, $since]
43|                );
44|
45|                return collect($results)->map(fn ($row) => [
46|                    'month' => $row->month,
47|                    'count' => (int) $row->count,
48|                ])->values();
49|            }
50|        );
51|
52|        return response()->json(['data' => $data]);
53|    }
54|
55|    /**
56|     * GET /api/hr/analytics/vacancy-trend — monthly vacancy count (units with zero personnel).
57|     */
58|    public function vacancyTrend(UnitScopedRequest $request): JsonResponse
59|    {
60|        $accessibleIds = $request->accessibleIds();
61|        $months = min((int) $request->get('months', 12), 24);
62|
63|        $data = Cache::remember(
64|            $this->hrAnalyticsCacheKey('vacancy_trend', $accessibleIds, $months),
65|            now()->addMinutes(5),
66|            function () use ($accessibleIds, $months) {
67|                $idArray = '{'.implode(',', array_map('intval', $accessibleIds)).'}';
68|                $results = DB::select(
69|                    "WITH accessible_units AS (
70|                        SELECT id FROM units WHERE id = ANY(?)
71|                    ),
72|                    month_series AS (
73|                        SELECT generate_series(
74|                            date_trunc('month', CURRENT_DATE) - make_interval(months => ?),
75|                            date_trunc('month', CURRENT_DATE),
76|                            '1 month'::interval
77|                        ) AS month_start
78|                    ),
79|                    personnel_counts AS (
80|                        SELECT
81|                            date_trunc('month', p.created_at) AS month_start,
82|                            p.u_id,
83|                            COUNT(*) AS personnel_count
84|                        FROM persons p
85|                        WHERE p.u_id = ANY(ARRAY(SELECT id FROM accessible_units))
86|                        GROUP BY date_trunc('month', p.created_at), p.u_id
87|                    )
88|                    SELECT
89|                        to_char(ms.month_start, 'YYYY-MM') AS month,
90|                        COUNT(au.id) - COUNT(pc.u_id) AS vacant_count
91|                    FROM month_series ms
92|                    CROSS JOIN accessible_units au
93|                    LEFT JOIN personnel_counts pc ON pc.month_start = ms.month_start AND pc.u_id = au.id
94|                    GROUP BY ms.month_start
95|                    ORDER BY ms.month_start DESC",
96|                    [$idArray, (string) $months]
97|                );
98|
99|                return collect($results)->map(fn ($row) => [
100|                    'month' => $row->month,
101|                    'count' => (int) $row->vacant_count,
102|                ]);
103|            }
104|        );
105|
106|        return response()->json(['data' => $data]);
107|    }
108|
109|    /**
110|     * GET /api/hr/analytics/staffing-ratio — personnel count per unit_type and per semat.
