3|use App\Models\Unit;
4|use App\Services\AccessService;
5|use Illuminate\Support\Facades\DB;
6|use Livewire\Attributes\Locked;
7|use Livewire\Component;
8|use Mary\Traits\Toast;
9|
10|return new class extends Component {
11|    use Toast;
12|
13|    #[Locked]
14|    public int $unitId;
15|    public ?array $unit = null;
16|    public ?string $geojson = null;
17|    public bool $hasBoundary = false;
18|
19|    public function mount(int $id): void
20|    {
21|        $this->unitId = $id;
22|        $this->loadUnit();
23|    }
24|
25|    /**
26|     * Issue #817: the org tree IS the authorization model — boundary reads
27|     * and writes must prove the unit sits inside the caller's reachable set.
28|     */
29|    private function assertUnitInScope(int $unitId): bool
30|    {
31|        $accessibleIds = app(AccessService::class)->accessibleUnitIds();
32|
33|        if (! in_array($unitId, $accessibleIds, true)) {
34|            $this->error('شما مجاز به مشاهده یا ویرایش این واحد نیستید.');
35|
36|            return false;
37|        }
38|
39|        return true;
40|    }
41|
42|    public function loadUnit(): void
43|    {
44|        // #817: unitId is a mount parameter but stays client-settable between
45|        // calls — #[Locked] alone only rejects tampering, it does not hide
46|        // other units. The explicit scope check is the fix.
47|        if (! $this->assertUnitInScope($this->unitId)) {
48|            $this->unit = null;
49|            $this->hasBoundary = false;
50|            $this->geojson = null;
51|
52|            return;
53|        }
54|
55|        $unit = Unit::with('boundary')->find($this->unitId);
56|
57|        if (! $unit) {
58|            $this->error('واحد یافت نشد.');
59|            return;
60|        }
61|
62|        $this->unit = $unit->toArray();
63|        $this->hasBoundary = $unit->boundary_id !== null;
64|        $this->geojson = $unit->boundary?->geojson;
65|    }
66|
67|    public function saveBoundary($geojsonData): void
68|    {
69|        // #817: scope-check before touching the boundary rows.
70|        if (! $this->assertUnitInScope($this->unitId)) {
71|            return;
72|        }
73|
74|        $feature = json_decode($geojsonData, true);
75|
76|        if (! isset($feature['geometry']['type']) || ! in_array($feature['geometry']['type'], ['Polygon', 'MultiPolygon'])) {
77|            $this->error('فقط نوع‌های Polygon یا MultiPolygon پشتیبانی می‌شوند.');
78|            return;
79|        }
80|
81|        $geometry = json_encode($feature['geometry']);
82|
83|        $unit = Unit::find($this->unitId);
84|        if (! $unit) return;
85|
86|        if ($unit->boundary_id) {
87|            DB::table('boundaries')
88|                ->where('id', $unit->boundary_id)
89|                ->update([
90|                    'boundary' => DB::raw("ST_GeomFromGeoJSON(" . DB::getPdo()->quote($geometry) . ")"),
91|                ]);
92|        } else {
93|            $boundaryId = DB::table('boundaries')->insertGetId([
94|                'boundary' => DB::raw("ST_GeomFromGeoJSON(" . DB::getPdo()->quote($geometry) . ")"),
95|            ]);
96|            $unit->update(['boundary_id' => $boundaryId]);
97|        }
98|
99|        $this->success('مرز با موفقیت ذخیره شد.');
100|        $this->loadUnit();
101|        $this->dispatch('boundaryUpdated');
102|    }
103|
104|    public function deleteBoundary(): void
105|    {
106|        // #817: scope-check before nulling the FK or deleting geometry.
107|        if (! $this->assertUnitInScope($this->unitId)) {
108|            return;
109|        }
110|
111|        $unit = Unit::find($this->unitId);
112|
113|        if (! $unit || ! $unit->boundary_id) {
114|            return;
115|        }
116|
117|        $boundaryId = $unit->boundary_id;
118|
119|        // #702: nulling boundary_id alone left the geometry row orphaned in
120|        // `boundaries` forever.
121|        //
122|        // ORDER MATTERS: units.boundary_id is ON DELETE CASCADE, so deleting the
123|        // `boundaries` row first would cascade-delete THIS unit (and any child
124|        // units). Null the FK first so the boundary row is unreferenced, then
125|        // remove it.
126|        try {
127|            DB::transaction(function () use ($unit, $boundaryId): void {
128|                $unit->update(['boundary_id' => null]);
129|                DB::table('boundaries')->where('id', $boundaryId)->delete();
130|            });
131|        } catch (\Throwable $e) {
132|            report($e);
133|            $this->error('حذف مرز ناموفق بود.');
134|
135|            return;
136|        }
137|
138|        $this->success('مرز حذف شد.');
139|        $this->loadUnit();
140|        $this->dispatch('boundaryUpdated');
141|    }
142|}; ?>
