198|    var mapTileTemplate = @js(config('map.tile_url_template', 'https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png'));
199|
200|    function initUnitMap() {
201|        var unitMap = L.map('unitMap').setView([36.558188, 48.716125], 8);
202|
203|        L.tileLayer(mapTileTemplate, {
204|            attribution: '&copy; Health-Dashboard',
205|            className: 'map-tiles'
206|        }).addTo(unitMap);
207|
208|        var drawnItems = new L.FeatureGroup();
209|        window._drawnItems = drawnItems;
210|        unitMap.addLayer(drawnItems);
